UTE"},{"grantee":"lomi_remote_exchange","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"}]}, {"signature": "public.lomi_approval_source_require_v2(public.consumer_approval_intent,boolean)", "owner": "lomi_migrator", "catalog_sha256": "87d5a8cff6ef6767c49cda14d23878b02c0a4349dc992c08dee4f3399e092a8f", "acl": [{"grantee":"lomi_migrator","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_runtime","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_remote_exchange","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"}]}, {"signature": "public.lomi_approval_consumed_proof_guard_v2()", "owner": "lomi_migrator", "catalog_sha256": "7a7bb88c144b0285b7383bdb0cd7985866f54f06a0c7d59f18fb818201f0d235", "acl": [{"grantee":"lomi_migrator","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_runtime","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_remote_exchange","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"}]}, {"signature": "public.lomi_approval_intent_guard_v2()", "owner": "lomi_migrator", "catalog_sha256": "645e3b7eb04fd7cbed103f2f0830b80a872b9ba64a6a7563ce8c976f3a24947e", "acl": [{"grantee":"lomi_migrator","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_runtime","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_remote_exchange","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"}]}, {"signature": "public.lomi_approval_flow_guard_v2()", "owner": "lomi_migrator", "catalog_sha256": "9e24955a076c933f5380d709c29c560697912f4caef2f3c6cfd988bdf4200924", "acl": [{"grantee":"lomi_migrator","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_runtime","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_remote_exchange","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"}]}, {"signature": "public.lomi_approval_exchange_complete_v2(uuid)", "owner": "lomi_migrator", "catalog_sha256": "4c90ef07831471098c84053a8403833add63e9c2e6101fc8f537374c4844b6e7", "acl": [{"grantee":"lomi_migrator","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_runtime","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_remote_exchange","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"}]}, {"signature": "public.lomi_approval_deferred_guard_v2()", "owner": "lomi_migrator", "catalog_sha256": "9850974a89aca4c42382200d977de38d7947e2fa9cc8a83577272d57ed09f371", "acl": [{"grantee":"lomi_migrator","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_runtime","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"},{"grantee":"lomi_remote_exchange","grantor":"lomi_migrator","grantable":false,"privilege":"EXECUTE"}]}]$deps$::jsonb;
 role_row record; dep jsonb;
 r jsonb; p record; state text; seen_old integer:=0; seen_new integer:=0;
 actual_acl jsonb;
BEGIN
 IF NOT current_setting('is_superuser')::boolean OR current_setting('server_version_num')::integer<>180006 THEN
  RAISE EXCEPTION 'operator and exact PostgreSQL 18.6 required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('lomi-auth:device-mutations-and-revoke-all:v1',0));
 -- Validate execution-owner sealing before either old-state or new-state path.
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='lomi_migrator' AND NOT rolsuper AND NOT rolcreaterole) THEN RAISE EXCEPTION 'routine migrator retains owner-bypass authority'; END IF;
 FOR role_row IN SELECT * FROM pg_roles WHERE rolname IN ('lomi_remote_inventory_owner','lomi_remote_pairing_write_owner','lomi_consumer_auth_body_owner') LOOP
  IF role_row.rolcanlogin OR role_row.rolinherit OR role_row.rolsuper OR role_row.rolcreatedb OR role_row.rolcreaterole OR role_row.rolreplication OR role_row.rolbypassrls OR (role_row.rolname='lomi_consumer_auth_body_owner' AND role_row.rolconfig IS NOT NULL)
   OR has_schema_privilege(role_row.oid,'public','CREATE') OR EXISTS(SELECT FROM pg_auth_members WHERE member=role_row.oid OR roleid=role_row.oid) THEN
   RAISE EXCEPTION 'execution owner retains excessive authority: %',role_row.rolname; END IF;
 END LOOP;
 IF (SELECT count(*) FROM pg_roles WHERE rolname IN ('lomi_remote_inventory_owner','lomi_remote_pairing_write_owner','lomi_consumer_auth_body_owner'))<>3 THEN RAISE EXCEPTION 'missing execution owner'; END IF;
 FOR dep IN SELECT value FROM jsonb_array_elements(deps) LOOP
  IF dep->>'catalog_sha256' IS NULL OR dep->'acl'='null'::jsonb THEN RAISE EXCEPTION 'unmeasured dependency catalog/ACL pins'; END IF;
  SELECT * INTO STRICT p FROM pg_proc WHERE oid=(dep->>'signature')::regprocedure;
  SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,
   'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantor,x.grantee,x.privilege_type,x.is_grantable),'[]'::jsonb)
   INTO actual_acl FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x;
  IF pg_get_userbyid(p.proowner)<>dep->>'owner' OR actual_acl IS DISTINCT FROM dep->'acl'
   OR encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')<>dep->>'catalog_sha256' THEN RAISE EXCEPTION 'unsealed dependency: %',dep->>'signature'; END IF;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(expected) LOOP
  IF r->>'old_catalog_sha256' IS NULL OR r->>'new_catalog_sha256' IS NULL OR r->'old_acl'='null'::jsonb OR r->'new_acl'='null'::jsonb THEN
   RAISE EXCEPTION 'unmeasured catalog/ACL pins: candidate cannot execute'; END IF;
  SELECT * INTO STRICT p FROM pg_proc WHERE oid=(r->>'signature')::regprocedure;
  SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,
   'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantor,x.grantee,x.privilege_type,x.is_grantable),'[]'::jsonb)
   INTO actual_acl FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x;
  IF pg_get_userbyid(p.proowner)<>r->>'owner' OR NOT p.prosecdef THEN
   RAISE EXCEPTION 'unexpected root owner/security/search_path: %',r->>'signature'; END IF;
  IF encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')=r->>'old_catalog_sha256' AND actual_acl=r->'old_acl' THEN seen_old:=seen_old+1;
  ELSIF encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')=r->>'new_catalog_sha256' AND actual_acl=r->'new_acl' THEN seen_new:=seen_new+1;
  ELSE RAISE EXCEPTION 'unexpected root definition/ACL: %',r->>'signature'; END IF;
 END LOOP;
 IF seen_new=3 THEN RETURN; END IF;
 IF seen_old<>3 OR seen_new<>0 THEN RAISE EXCEPTION 'mixed catalog state rejected'; END IF;
 EXECUTE $literal0$CREATE OR REPLACE FUNCTION public.lomi_consumer_inventory(p_account uuid,p_consumer uuid,p_session text,p_class text,p_epoch bigint,p_expiry_ms bigint,p_manage boolean,p_hash bytea)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE stamp timestamptz; h record; hosts jsonb:='[]'; result jsonb; public_context jsonb; live boolean; host_count integer:=0;
BEGIN
 IF current_user<>'lomi_remote_inventory_owner' THEN RAISE EXCEPTION 'inventory unavailable' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('lomi-auth:device-mutations-and-revoke-all:v1',0));
 stamp:=clock_timestamp();
 PERFORM public.lomi_consumer_scalar_recheck_v2(p_account,p_consumer,p_session,p_class,p_epoch,p_expiry_ms,p_manage,p_hash);
 SELECT jsonb_build_object('accountId',c."accountId",'consumerAuthorizationId',c.id,'accountSessionId',c."accountSessionId",
  'class',c."clientClass",'expiresAt',floor(extract(epoch FROM c."expiresAt"))::bigint::text,'canManageAccount',c."canManageAccount")
 INTO STRICT public_context FROM public.consumer_authorization c WHERE c.id=p_consumer;
 FOR h IN
  SELECT i."hostId",i."finalizedIdentity",i."hostKeyFingerprint",r."runtimeId",r.generation,r."hostAccessEpoch",
   r."leaseExpiresAt",r."freshUntil",r.workspaces,f."accessExpiresAt",f."idleExpiresAt"
  FROM public.host_identity i
  JOIN public.host_authorization f ON f."hostId"=i."hostId" AND f."accountId"=i."accountId" AND f."hostAccessEpoch"=i."accessEpoch"
  JOIN public.host_runtime r ON r."hostId"=i."hostId" AND r."authorizationId"=f.id AND r."hostAccessEpoch"=i."accessEpoch"
  WHERE i."accountId"=p_account AND i."finalizedIdentity" IS NOT NULL AND f.confirmed AND NOT f.revoked AND f."clientClass"='host'
   AND f."approvedAccountEpoch"=p_epoch AND r.generation>0 AND r."publicationSeq">0
   AND jsonb_typeof(r.workspaces)='array' AND jsonb_array_length(r.workspaces)>0
  ORDER BY i."hostId" LIMIT 257
 LOOP
  host_count:=host_count+1;
  IF host_count>256 OR NOT public.lomi_host_runtime_publication_valid(h.workspaces) THEN
   RAISE EXCEPTION 'inventory resource limit' USING ERRCODE='LR002'; END IF;
  live:=h."accessExpiresAt">stamp AND h."idleExpiresAt">stamp AND h."leaseExpiresAt">stamp AND h."freshUntil">stamp;
  hosts:=hosts||jsonb_build_array(jsonb_build_object(
   'hostId',h."hostId",'identity',h."finalizedIdentity",'identityFingerprint',encode(h."hostKeyFingerprint",'hex'),
   'runtime',jsonb_build_object('runtimeId',h."runtimeId",'runtimeGeneration',h.generation::text,'hostAccessEpoch',h."hostAccessEpoch"::text),
   'status',CASE WHEN live THEN 'online' ELSE 'offline' END,'workspaces',CASE WHEN live THEN h.workspaces ELSE '[]'::jsonb END));
  -- jsonb text includes whitespace, giving a conservative canonical JSON bound.
  IF octet_length(jsonb_build_object('authorization',public_context,'hosts',hosts)::text)>1048576 THEN
   RAISE EXCEPTION 'inventory resource limit' USING ERRCODE='LR002'; END IF;
 END LOOP;
 result:=jsonb_build_object('authorization',public_context,'hosts',hosts);
 RETURN result;
END $$;$literal0$;
 EXECUTE $literal1$CREATE OR REPLACE FUNCTION public.lomi_consumer_assertion_recheck(p_account uuid,p_consumer uuid,p_session text,p_class text,p_epoch bigint,p_expiry_ms bigint,p_manage boolean,p_hash bytea)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF current_user<>'lomi_remote_inventory_owner' THEN RAISE EXCEPTION 'consumer assertion unavailable' USING ERRCODE='42501'; END IF;
 PERFORM public.lomi_consumer_scalar_recheck_v2(p_account,p_consumer,p_session,p_class,p_epoch,p_expiry_ms,p_manage,p_hash);
END $$;$literal1$;
 EXECUTE $literal2$CREATE OR REPLACE FUNCTION public.lomi_consumer_recipient_recheck(p_account uuid,p_consumer uuid)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE c public.consumer_authorization;
BEGIN
 IF current_user<>'lomi_remote_inventory_owner' THEN RAISE EXCEPTION 'recipient unavailable' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('lomi-auth:device-mutations-and-revoke-all:v1',0));
 SELECT * INTO c FROM public.consumer_authorization WHERE id=p_consumer AND "accountId"=p_account;
 IF NOT FOUND THEN RAISE EXCEPTION 'recipient unavailable' USING ERRCODE='28000'; END IF;
 PERFORM public.lomi_consumer_principal_live_v2(c);
 RETURN jsonb_build_object('accountId',c."accountId",'consumerAuthorizationId',c.id,'accountSessionId',c."accountSessionId",'class',c."clientClass",
  'authorizationEpoch',c."authorizationEpoch"::text,'expiresAtMs',(extract(epoch FROM c."expiresAt")*1000)::bigint::text,'canManageAccount',c."canManageAccount");
END $$;$literal2$;
 -- Scalar roots are internal only. Change only this allowlisted root ACL;
 -- all remaining scalar-surface retirement belongs to later reviewed ops sealing.
 REVOKE ALL ON FUNCTION public.lomi_consumer_inventory(uuid,uuid,text,text,bigint,bigint,boolean,bytea) FROM PUBLIC,lomi_runtime,lomi_remote_api,lomi_remote_exchange,lomi_remote_runtime_owner;
 GRANT EXECUTE ON FUNCTION public.lomi_consumer_inventory(uuid,uuid,text,text,bigint,bigint,boolean,bytea) TO lomi_remote_pairing_write_owner;
 -- Revalidate all three definitions, owners and post-state ACLs atomically.
 FOR r IN SELECT value FROM jsonb_array_elements(expected) LOOP
  SELECT * INTO STRICT p FROM pg_proc WHERE oid=(r->>'signature')::regprocedure;
  SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,
   'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantor,x.grantee,x.privilege_type,x.is_grantable),'[]'::jsonb)
   INTO actual_acl FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x;
  IF pg_get_userbyid(p.proowner)<>r->>'owner' OR NOT p.prosecdef
   OR encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')<>r->>'new_catalog_sha256' OR actual_acl IS DISTINCT FROM r->'new_acl' THEN
   RAISE EXCEPTION 'new root catalog mismatch: %',r->>'signature'; END IF;
 END LOOP;
END $operator$;
COMMIT;
